<script setup lang="ts">
import { computed, ref } from 'vue'
import { onLoad, onShow } from '@dcloudio/uni-app'
import AppButton from '@/components/AppButton.vue'
import AppIcon from '@/components/AppIcon.vue'
import AppNavbar from '@/components/AppNavbar.vue'
import AppPage from '@/components/AppPage.vue'
import BaseCard from '@/components/BaseCard.vue'
import BottomActionBar from '@/components/BottomActionBar.vue'
import StatusTag from '@/components/StatusTag.vue'
import StepProgress from '@/components/StepProgress.vue'
import { usePageResource } from '@/composables/usePageResource'
import { residentMallService } from '@/services/mall'
import { residentAfterSaleService } from '@/services/after-sale'
import type { ResidentAfterSaleView, AfterSaleEligibility } from '@/types/after-sale'
import { openSubPage } from '@/utils/navigation'

const orderId = ref('')
const afterSales = ref<ResidentAfterSaleView[]>([])
const eligibility = ref<Record<string, AfterSaleEligibility>>({})
const { status, data, errorMessage, load } = usePageResource(async () => {
  const order = await residentMallService.getOrder(orderId.value)
  afterSales.value = await residentAfterSaleService.getOrderRecords(order.id)
  const entries = await Promise.all(order.items.map(async item => [item.skuId, await residentAfterSaleService.getEligibility(order.id, item.skuId)] as const))
  eligibility.value = Object.fromEntries(entries)
  return order
})
const itemRecords = (skuId: string) => afterSales.value.filter(record => record.skuId === skuId)
const applyAfterSale = (skuId: string) => openSubPage('/pages/after-sale/apply/index?orderId=' + encodeURIComponent(orderId.value) + '&skuId=' + encodeURIComponent(skuId))
const viewAfterSale = (id: string) => openSubPage('/pages/after-sale/detail/index?id=' + encodeURIComponent(id))
const money = (value: number) => (value / 100).toFixed(2)
const displayStatus = computed(() => {
  const order = data.value
  if (!order) return ''
  if (order.tradeStatus === '已关闭') return '已关闭'
  if (!['Mock成功', '支付成功'].includes(order.paymentStatus)) return '待支付'
  if (order.tradeStatus === '已完成') return '已完成'
  return order.fulfillmentStatus
})
const steps = computed(() => data.value?.fulfillmentMethod === '普通物流' ? ['已支付', '商户备货', '待发货', '已发货', '已完成'] : data.value?.fulfillmentMethod === '商户配送' ? ['已支付', '商户备货', '配送中', '已送达', '已完成'] : data.value?.fulfillmentMethod === '社区自提' ? ['已支付', '商户备货', '待自提', '已核销', '已完成'] : ['已支付', '待核销', '已核销', '已完成'])
const currentStep = computed(() => { const status = displayStatus.value; const map: Record<string, number> = { '待支付': 1, '待备货': 2, '待配送': 2, '待发货': 3, '已发货': 4, '配送中': 3, '已送达': 4, '待自提': 3, '待核销': 2, '已核销': 3, '已完成': steps.value.length }; return map[status] || 1 })
const canConfirmReceipt = computed(() => ['Mock成功', '支付成功'].includes(data.value?.paymentStatus || '') && !(data.value?.fulfillmentBlocked ?? data.value?.afterSaleStatus === '售后处理中') && (displayStatus.value === '已送达' || (data.value?.fulfillmentMethod === '普通物流' && displayStatus.value === '已发货')))
const timeline = computed(() => data.value?.timeline || [])
const tone = computed(() => displayStatus.value === '已完成' ? 'success' : displayStatus.value === '已关闭' ? 'error' : 'pending')
const confirmReceipt = () => uni.showModal({ title: '确认收货', content: '确认后订单将完成。', success: async ({ confirm }) => { if (confirm && data.value) { try { await residentMallService.confirmReceipt(data.value.id); uni.showToast({ title: '已确认收货', icon: 'success' }); load() } catch (error) { uni.showToast({ title: error instanceof Error ? error.message : '操作失败', icon: 'none' }) } } } })
const cancel = () => uni.showModal({ title: '取消订单', content: '取消将关闭同一交易的全部未支付商户订单，并释放库存。', success: async ({ confirm }) => { if (confirm && data.value) { try { await residentMallService.cancelOrder(data.value.id); load() } catch (error) { uni.showToast({ title: error instanceof Error ? error.message : '操作失败', icon: 'none' }) } } } })
onLoad((options) => { orderId.value = typeof options?.id === 'string' ? options.id : ''; load() }); onShow(load)
</script>

<template>
  <AppPage :status="status" :state-message="errorMessage" secondary :with-bottom-action="true" @retry="load">
    <template #navbar><AppNavbar title="订单详情" centered show-back /></template>
    <view v-if="data" class="stack order-detail-page"><BaseCard class="status-hero" :class="`status-hero--${tone}`"><view><StatusTag :tone="tone">{{ displayStatus }}</StatusTag><text>{{ data.fulfillmentMethod }}</text></view><text>{{ displayStatus === '待支付' ? '订单已提交，请完成支付后等待商户履约。' : displayStatus === '已完成' ? '订单已完成。' : '当前履约状态已同步，请按实际方式查看下一步。' }}</text></BaseCard><BaseCard><view class="section-title"><AppIcon name="car" :size="20" /><text>履约进度</text></view><StepProgress :steps="steps" :current="currentStep" :completed="Math.max(0, currentStep - 1)" /><view class="timeline"><view v-for="event in timeline" :key="`${event.time}${event.title}`"><text>{{ event.title }}</text><text>{{ event.description }}</text><text>{{ event.time }}</text></view></view></BaseCard><BaseCard><view class="section-title"><AppIcon :name="['商户配送', '普通物流'].includes(data.fulfillmentMethod) ? 'location' : 'store'" :size="20" /><text>{{ ['商户配送', '普通物流'].includes(data.fulfillmentMethod) ? '配送与收货信息' : data.fulfillmentMethod === '社区自提' ? '自提与核销信息' : '门店核销信息' }}</text></view><view v-if="['商户配送', '普通物流'].includes(data.fulfillmentMethod)" class="fulfillment-info"><text>{{ data.contactSnapshot.name }} {{ data.contactSnapshot.mobile }}</text><text>{{ data.addressSnapshot?.region }}{{ data.addressSnapshot?.detail }}</text><text v-if="data.buyerRemark" class="remark">买家留言：{{ data.buyerRemark }}</text></view><view v-else class="fulfillment-info"><text>{{ data.pickupPoint }}</text><text>联系人：{{ data.contactSnapshot.name }} {{ data.contactSnapshot.mobile }}</text><view v-if="data.verificationCode" class="verify-code"><text>核销码</text><text>{{ data.verificationCode }}</text><text>{{ data.verificationStatus === '已核销' ? '已完成核销' : '到现场请向工作人员出示，核对后确认。' }}</text></view><text v-if="data.buyerRemark" class="remark">买家留言：{{ data.buyerRemark }}</text></view></BaseCard><BaseCard v-if="data.fulfillmentMethod === '普通物流' && data.logisticsNo"><view class="section-title"><AppIcon name="car" :size="20" /><text>物流发货信息</text></view><view class="plain-row"><text>物流公司</text><text>{{ data.logisticsName }}</text></view><view class="plain-row"><text>物流单号</text><text>{{ data.logisticsNo }}</text></view><view class="plain-row"><text>发货时间</text><text>{{ data.shippedAt }}</text></view></BaseCard><BaseCard><view class="section-title"><AppIcon name="store" :size="20" /><text>{{ data.merchantName }}（{{ data.storeName }}）</text></view><view v-for="item in data.items" :key="item.skuId" class="detail-item"><image :src="item.productImage" mode="aspectFill" /><view><text>{{ item.productName }}</text><text>规格：{{ item.skuName }}</text><text class="price">¥{{ money(item.unitPrice) }} × {{ item.quantity }}</text><view class="item-after-sale"><AppButton v-if="eligibility[item.skuId]?.allowRefund" variant="quiet" @click="applyAfterSale(item.skuId)">申请售后</AppButton><AppButton v-if="itemRecords(item.skuId).length" variant="quiet" @click="viewAfterSale(itemRecords(item.skuId)[0].id)">查看售后</AppButton><text v-if="!eligibility[item.skuId]?.allowRefund" class="eligibility-reason">{{ eligibility[item.skuId]?.reason }}</text></view></view></view><view class="amount-row"><text>商品金额</text><text>¥{{ money(data.goodsAmount) }}</text></view><view class="amount-row"><text>配送费</text><text>¥{{ money(data.deliveryFee) }}</text></view><view class="amount-total"><text>实付金额</text><text>¥{{ money(data.paidAmount || data.payableAmount) }}</text></view></BaseCard><BaseCard><view class="section-title"><AppIcon name="bill" :size="20" /><text>订单信息</text></view><view class="plain-row"><text>订单号</text><text>{{ data.no }}</text></view><view class="plain-row"><text>支付状态</text><text>{{ data.paymentStatus }}</text></view><view class="plain-row"><text>售后/退款</text><text>{{ data.afterSaleStatus }} · {{ data.refundStatus }}</text></view></BaseCard><BaseCard v-if="afterSales.length"><view class="section-title"><text>售后记录</text><text>{{ data.afterSaleSummary }}</text></view><view v-for="record in afterSales" :key="record.id" class="after-sale-record"><text>{{ record.item.productName }} · {{ record.item.skuName }} · {{ record.quantity }} 件</text><text>{{ record.typeLabel }} · {{ record.statusLabel }} · ¥{{ money(record.applyRefundAmount) }}</text><AppButton variant="quiet" @click="viewAfterSale(record.id)">查看处理进度</AppButton></view></BaseCard></view>
    <BottomActionBar><AppButton v-if="displayStatus === '待支付'" variant="secondary" @click="cancel">取消订单</AppButton><AppButton v-if="displayStatus === '待支付'" @click="openSubPage(`/pages/pay/result/index?orderId=${data?.id || ''}`)">去支付</AppButton><AppButton v-else-if="canConfirmReceipt" @click="confirmReceipt">确认收货</AppButton><AppButton v-else variant="secondary" @click="openSubPage('/pages/mall/order-list/index')">返回订单列表</AppButton></BottomActionBar>
  </AppPage>
</template>

<style scoped lang="scss">
.order-detail-page { gap:$space-3; }.status-hero { display:flex; flex-direction:column; gap:$space-2; background:$color-primary; color:#fff; }.status-hero--success { background:#287c39; }.status-hero--error { background:$color-error; }.status-hero > view { display:flex; align-items:center; gap:$space-2; }.status-hero :deep(.status-tag) { min-height:24px; border:1px solid rgba(255,255,255,.5); background:rgba(255,255,255,.16); color:#fff; }.status-hero > view text { font-size:13px; }.status-hero > text { font-size:16px; font-weight:600; line-height:23px; }.section-title { display:flex; align-items:center; gap:$space-2; padding-bottom:$space-3; border-bottom:1px solid rgba(225,228,230,.72); font-size:17px; font-weight:700; }.timeline { display:flex; flex-direction:column; gap:$space-3; padding:$space-3 0 0 $space-2; }.timeline > view { position:relative; display:flex; flex-direction:column; gap:2px; padding-left:$space-3; color:$color-text-secondary; font-size:12px; line-height:18px; }.timeline > view::before { position:absolute; top:5px; left:0; width:7px; height:7px; border-radius:50%; background:$color-primary; content:''; }.timeline > view text:first-child { color:$color-text-primary; font-size:14px; font-weight:600; }.timeline > view text:last-child { color:$color-text-disabled; }.fulfillment-info { display:flex; flex-direction:column; gap:$space-2; padding-top:$space-3; font-size:15px; line-height:21px; }.fulfillment-info > text:first-child { font-size:16px; font-weight:700; }.remark { padding:$space-2; border-radius:$radius-sm; background:$color-warning-light; color:$color-warning; }.verify-code { display:flex; align-items:baseline; flex-wrap:wrap; gap:$space-2; padding:$space-3; border-radius:$radius-md; background:$color-primary-light; color:$color-primary; }.verify-code text:first-child { font-size:13px; }.verify-code text:nth-child(2) { font-size:22px; font-weight:700; letter-spacing:1px; }.verify-code text:last-child { width:100%; color:$color-text-secondary; font-size:12px; }.detail-item { display:flex; align-items:center; gap:$space-3; padding:$space-3 0; border-bottom:1px solid rgba(225,228,230,.72); }.detail-item image { width:64px; height:64px; border-radius:$radius-md; background:$color-group-bg; }.detail-item > view { display:flex; flex:1; flex-direction:column; gap:3px; }.detail-item > view text:first-child { font-size:16px; font-weight:600; }.detail-item > view text:nth-child(2) { color:$color-text-secondary; font-size:13px; }.price { color:$color-accent; font-size:15px !important; font-weight:700; }.amount-row,.plain-row,.amount-total { display:flex; align-items:center; justify-content:space-between; gap:$space-3; padding-top:$space-3; color:$color-text-secondary; font-size:14px; }.amount-total { margin-top:$space-3; border-top:1px dashed $color-border; color:$color-text-primary; font-weight:700; }.amount-total text:last-child { color:$color-accent; font-size:22px; }.plain-row text:last-child { color:$color-text-primary; text-align:right; }.after-sale-note { padding:$space-3; border-radius:$radius-md; background:$color-group-bg; color:$color-text-secondary; font-size:12px; line-height:18px; }
</style>

<style scoped lang="scss">
.plain-row { align-items:flex-start; }.plain-row text:last-child { min-width:0; flex:1; overflow-wrap:anywhere; }.fulfillment-info { overflow-wrap:anywhere; }.detail-item > view { min-width:0; overflow-wrap:anywhere; }.verify-code text:nth-child(2) { max-width:100%; overflow-wrap:anywhere; }
</style>
<style scoped lang="scss">.detail-item image { flex:none; }.detail-item > view { min-width:0; }.item-after-sale { display:flex; flex-wrap:wrap; gap:4px; }.eligibility-reason { width:100%; color:$color-text-secondary; font-size:13px; line-height:20px; overflow-wrap:anywhere; }.after-sale-record { display:flex; flex-direction:column; gap:8px; padding-top:12px; font-size:14px; line-height:22px; overflow-wrap:anywhere; }.section-title { flex-wrap:wrap; }.section-title > text:last-child:not(:first-child) { font-size:13px; color:$color-text-secondary; }</style>